"""Pydantic data models for the Contracter legal document triage application."""

from __future__ import annotations

from typing import Literal
from pydantic import BaseModel, Field

DEFAULT_LEGAL_DISCLAIMER: str = (
    "DISCLAIMER: This analysis is generated by an automated triage system and does NOT "
    "constitute legal advice. The system is an assistive tool and not a qualified lawyer. "
    "Please consult a licensed legal professional for formal legal advice or binding interpretation."
)


class DocumentChunk(BaseModel):
    """Represents a discrete text chunk extracted from a document with location metadata."""

    content: str = Field(..., description="Text content of the chunk")
    page_number: int = Field(..., description="1-indexed page number where this chunk originates", ge=1)
    chunk_index: int = Field(..., description="0-indexed global sequence order of this chunk", ge=0)
    start_char: int = Field(..., description="Character offset where chunk starts on its page", ge=0)
    end_char: int = Field(..., description="Character offset where chunk ends on its page", ge=0)
    source_file: str = Field(..., description="Original filename or path of the source document")


class RetrievedChunk(BaseModel):
    """A chunk returned by vector search, carrying both text and citation metadata.

    Exposing retrieval results makes it possible to measure retrieval quality
    (recall, precision, ranking) separately from generation quality, which is
    the whole point of a RAG evaluation harness.
    """

    chunk_id: str = Field(..., description="Stable identifier of the chunk in the vector store")
    content: str = Field(..., description="Text content of the retrieved chunk")
    page_number: int = Field(default=1, description="1-indexed source page", ge=1)
    chunk_index: int = Field(default=0, description="0-indexed chunk order in the document", ge=0)
    start_char: int = Field(default=0, description="Character offset where the chunk starts", ge=0)
    end_char: int = Field(default=0, description="Character offset where the chunk ends", ge=0)
    source_file: str = Field(default="", description="Original source filename")
    distance: float | None = Field(default=None, description="Vector distance from the query")


class UploadResponse(BaseModel):
    """Response returned upon successful document upload and chunking."""

    document_id: str = Field(..., description="Unique identifier generated for the uploaded document")
    filename: str = Field(..., description="Original filename of the uploaded document")
    num_chunks: int = Field(..., description="Total number of chunks produced from the document", ge=0)
    num_pages: int = Field(..., description="Total number of pages extracted from the document", ge=0)


class QueryRequest(BaseModel):
    """Payload for querying a triaged document."""

    document_id: str = Field(..., description="Identifier of the target document")
    question: str = Field(..., description="Natural language question to ask about the document", min_length=1)


class CitedPassage(BaseModel):
    """Verbatim quotation from the document supporting a legal finding."""

    text: str = Field(..., description="Exact quote from the document source")
    page_number: int = Field(..., description="1-indexed page number containing the passage", ge=1)
    start_char: int = Field(default=0, description="Start character offset on the source page", ge=0)
    end_char: int = Field(default=0, description="End character offset on the source page", ge=0)


class ClauseAnalysis(BaseModel):
    """Detailed legal analysis of an extracted clause or contract condition."""

    clause_type: str = Field(
        ...,
        description="Type of clause (e.g., 'obligation', 'deadline', 'penalty', 'termination', 'indemnity', 'confidentiality')",
    )
    plain_language_summary: str = Field(
        ...,
        description="Plain-language explanation of what this clause requires, restricts, or specifies",
    )
    cited_passages: list[CitedPassage] = Field(
        default_factory=list,
        description="List of verbatim citations supporting this clause analysis",
    )
    confidence: Literal["high", "medium", "low"] = Field(
        default="medium",
        description="Confidence level regarding the accuracy of this extraction",
    )


class QueryResponse(BaseModel):
    """Complete response returned to the user for a legal query."""

    answer: str = Field(..., description="Synthesized plain-language answer to the user's question")
    answer_status: Literal["answered", "partial", "silent"] = Field(
        default="answered",
        description=(
            "Whether the document fully answers the question (answered), answers "
            "part of it while remaining silent on another part (partial), or is "
            "entirely silent (silent)"
        ),
    )
    clauses: list[ClauseAnalysis] = Field(
        default_factory=list,
        description="Detailed breakdown of relevant legal clauses detected in context",
    )
    disclaimer: str = Field(
        default=DEFAULT_LEGAL_DISCLAIMER,
        description="Prominent legal disclaimer regarding automated analysis",
    )
    uncertainty_notes: list[str] = Field(
        default_factory=list,
        description="Explicit notes identifying items the document is silent on or where ambiguity exists",
    )


class DocumentSummary(BaseModel):
    """High-level summary of an entire legal contract or agreement."""

    document_id: str = Field(..., description="Identifier of the summarized document")
    filename: str = Field(..., description="Original filename of the document")
    key_clauses: list[ClauseAnalysis] = Field(
        default_factory=list,
        description="Collection of notable clauses classified across the document",
    )
    overall_summary: str = Field(
        ...,
        description="Comprehensive executive summary of the document purpose and terms",
    )
    disclaimer: str = Field(
        default=DEFAULT_LEGAL_DISCLAIMER,
        description="Prominent legal disclaimer regarding automated analysis",
    )
